import{describe,expect,it}from"vitest";import{operationalEmail,operationalPersonas}from"./operational-personas.mjs";describe("factory de sessões",()=>{it("possui 14 personas Auth e visitante separado",()=>expect(Object.keys(operationalPersonas)).toHaveLength(14));it("usa identidades sintéticas determinísticas",()=>expect(Object.keys(operationalPersonas).every(p=>operationalEmail(p).endsWith("@comun.test"))).toBe(true));it("não compartilha identidade",()=>expect(new Set(Object.keys(operationalPersonas).map(operationalEmail)).size).toBe(14))});
